-- Generated by ekos-lakehouse (RFC 0195) from marts/inventory_by_store_rating.md. Approve by merging; do not edit.
{{ config(materialized='table', schema='gold', alias='inventory_by_store_rating') }}

select
    "inventory"."store_id" as "store",
    "film"."rating" as "rating",
    count("inventory"."inventory_id") as "copies",
    count(distinct "inventory"."film_id") as "titles"
from {{ ref('public__inventory') }} as "inventory"
left join {{ ref('public__film') }} as "film"
    on "inventory"."film_id" = "film"."film_id"
group by "inventory"."store_id", "film"."rating"
